   166→        total_active_balance,
   167→        churn_limit,
   168→        fork_name,
   169→    };
   170→
   171→    // Contexts that require immutable access to `state`.
   172→    let slashings_ctxt = &SlashingsContext::new(state, state_ctxt, spec)?;
   173→    let mut next_epoch_cache = PreEpochCache::new_for_next_epoch(state)?;
   174→
   175→    let pending_deposits_ctxt = if fork_name.electra_enabled() && conf.pending_deposits {
   176→        Some(PendingDepositsContext::new(state, spec, &conf)?)
   177→    } else {
   178→        None
   179→    };
   180→
   181→    let mut earliest_exit_epoch = state.earliest_exit_epoch().ok();
   182→    let mut exit_balance_to_consume = state.exit_balance_to_consume().ok();
   183→    let validators_in_consolidations = get_validators_in_consolidations(state);
   184→
   185→    // Split the state into several disjoint mutable borrows.
   186→    let (
   187→        validators,
   188→        balances,
   189→        previous_epoch_participation,
   190→        current_epoch_participation,
   191→        inactivity_scores,
   192→        progressive_balances,
   193→        exit_cache,
   194→        epoch_cache,
   195→    ) = state.mutable_validator_fields()?;
   196→
   197→    let num_validators = validators.len();
   198→
   199→    // Take a snapshot of the validators and participation before mutating. This is used for
   200→    // informational purposes (e.g. by the validator monitor).
   201→    let summary = ParticipationEpochSummary::new(
   202→        validators.clone(),
   203→        previous_epoch_participation.clone(),
   204→        current_epoch_participation.clone(),
   205→        previous_epoch,
   206→        current_epoch,
   207→    );
   208→
   209→    // Compute shared values required for different parts of epoch processing.
   210→    let rewards_ctxt = &RewardsAndPenaltiesContext::new(progressive_balances, state_ctxt, spec)?;
   211→
   212→    let mut activation_queues = if !fork_name.electra_enabled() {
   213→        let activation_queue = epoch_cache
   214→            .activation_queue()?
   215→            .get_validators_eligible_for_activation(
   216→                finalized_checkpoint.epoch,
   217→                activation_churn_limit as usize,
   218→            );
   219→        let next_epoch_activation_queue = ActivationQueue::default();
   220→        Some((activation_queue, next_epoch_activation_queue))
   221→    } else {
   222→        None
   223→    };
   224→    let effective_balances_ctxt = &EffectiveBalancesContext::new(spec)?;
   225→
   226→    // Iterate over the validators and related fields in one pass.
   227→    let mut validators_iter = validators.iter_cow();
   228→    let mut balances_iter = balances.iter_cow();
   229→    let mut inactivity_scores_iter = inactivity_scores.iter_cow();
   230→
   231→    for (index, &previous_epoch_participation, &current_epoch_participation) in izip!(
   232→        0..num_validators,
   233→        previous_epoch_participation.iter(),
   234→        current_epoch_participation.iter(),
   235→    ) {
   236→        let (_, mut validator) = validators_iter
   237→            .next_cow()
   238→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   239→        let (_, mut balance) = balances_iter
   240→            .next_cow()
   241→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   242→        let (_, mut inactivity_score) = inactivity_scores_iter
   243→            .next_cow()
   244→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   245→
   246→        let is_active_current_epoch = validator.is_active_at(current_epoch);
   247→        let is_active_previous_epoch = validator.is_active_at(previous_epoch);
   248→        let is_eligible = is_active_previous_epoch
   249→            || (validator.slashed && previous_epoch.safe_add(1)? < validator.withdrawable_epoch);
   250→
   251→        let base_reward = if is_eligible {
   252→            epoch_cache.get_base_reward(index)?
   253→        } else {
   254→            0
   255→        };
   256→
   257→        let validator_info = &ValidatorInfo {
   258→            index,
   259→            effective_balance: validator.effective_balance,
   260→            base_reward,
   261→            is_eligible,
   262→            is_slashed: validator.slashed,
   263→            is_active_current_epoch,
   264→            is_active_previous_epoch,
   265→            previous_epoch_participation,
   266→            current_epoch_participation,
   267→        };
   268→
   269→        if current_epoch != E::genesis_epoch() {
   270→            // `process_inactivity_updates`
   271→            if conf.inactivity_updates {
   272→                process_single_inactivity_update(
   273→                    &mut inactivity_score,
   274→                    validator_info,
   275→                    state_ctxt,
   276→                    spec,
   277→                )?;
   278→            }
   279→
   280→            // `process_rewards_and_penalties`
   281→            if conf.rewards_and_penalties {
   282→                process_single_reward_and_penalty(
   283→                    &mut balance,
   284→                    &inactivity_score,
   285→                    validator_info,
   286→                    rewards_ctxt,
   287→                    state_ctxt,
   288→                    spec,
   289→                )?;
   290→            }
   291→        }
   292→
   293→        // `process_registry_updates`
   294→        if conf.registry_updates {
   295→            let activation_queue_refs = activation_queues
   296→                .as_mut()
   297→                .map(|(current_queue, next_queue)| (&*current_queue, next_queue));
   298→            process_single_registry_update(
   299→                &mut validator,
   300→                validator_info,
   301→                exit_cache,
   302→                activation_queue_refs,
   303→                state_ctxt,
   304→                earliest_exit_epoch.as_mut(),
   305→                exit_balance_to_consume.as_mut(),
   306→                spec,
   307→            )?;
   308→        }
   309→
   310→        // `process_slashings`
   311→        if conf.slashings {
   312→            process_single_slashing(&mut balance, &validator, slashings_ctxt, state_ctxt, spec)?;
   313→        }
   314→
   315→        // `process_pending_deposits`
   316→        if let Some(pending_balance_deposits_ctxt) = &pending_deposits_ctxt {
   317→            process_pending_deposits_for_validator(
   318→                &mut balance,
   319→                validator_info,
   320→                pending_balance_deposits_ctxt,
   321→            )?;
   322→        }
   323→
   324→        // `process_effective_balance_updates`
   325→        if conf.effective_balance_updates {
   326→            if validators_in_consolidations.contains(&validator_info.index) {
   327→                process_single_dummy_effective_balance_update(
   328→                    validator_info.index,
   329→                    &validator,
   330→                    &mut next_epoch_cache,
   331→                    state_ctxt,
   332→                )?;
   333→            } else {
   334→                process_single_effective_balance_update(
   335→                    validator_info.index,
   336→                    *balance,
   337→                    &mut validator,
   338→                    validator_info.current_epoch_participation,
   339→                    &mut next_epoch_cache,
   340→                    progressive_balances,
   341→                    effective_balances_ctxt,
   342→                    state_ctxt,
   343→                    spec,
   344→                )?;
   345→            }
   346→        }
   347→    }
   348→
   349→    if conf.registry_updates && fork_name.electra_enabled() {
   350→        if let Ok(earliest_exit_epoch_state) = state.earliest_exit_epoch_mut() {
   351→            *earliest_exit_epoch_state =
   352→                earliest_exit_epoch.ok_or(Error::MissingEarliestExitEpoch)?;
   353→        }
   354→        if let Ok(exit_balance_to_consume_state) = state.exit_balance_to_consume_mut() {
   355→            *exit_balance_to_consume_state =
   356→                exit_balance_to_consume.ok_or(Error::MissingExitBalanceToConsume)?;
   357→        }
   358→    }
   359→
   360→    // Finish processing pending balance deposits if relevant.
   361→    //
   362→    // This *could* be reordered after `process_pending_consolidations` which pushes only to the end
   363→    // of the `pending_deposits` list. But we may as well preserve the write ordering used
   364→    // by the spec and do this first.
   365→    if let Some(ctxt) = pending_deposits_ctxt {
   366→        let mut new_balance_deposits = List::try_from_iter(
   367→            state
   368→                .pending_deposits()?
   369→                .iter_from(ctxt.next_deposit_index)?
