   373→            new_balance_deposits.push(deposit)?;
   374→        }
   375→        *state.pending_deposits_mut()? = new_balance_deposits;
   376→        *state.deposit_balance_to_consume_mut()? = ctxt.deposit_balance_to_consume;
   377→
   378→        // `new_validator_deposits` may contain multiple deposits with the same pubkey where
   379→        // the first deposit creates the new validator and the others are topups.
   380→        // Each item in the vec is a (pubkey, validator_index)
   381→        let mut added_validators = Vec::new();
   382→        for deposit in ctxt.new_validator_deposits {
   383→            let deposit_data = DepositData {
   384→                pubkey: deposit.pubkey,
   385→                withdrawal_credentials: deposit.withdrawal_credentials,
   386→                amount: deposit.amount,
   387→                signature: deposit.signature,
   388→            };
   389→            // Only check the signature if this is the first deposit for the validator,
   390→            // following the logic from `apply_pending_deposit` in the spec.
   391→            if let Some(validator_index) = state.get_validator_index(&deposit_data.pubkey)? {
   392→                state
   393→                    .get_balance_mut(validator_index)?
   394→                    .safe_add_assign(deposit_data.amount)?;
   395→            } else if is_valid_deposit_signature(&deposit_data, spec).is_ok() {
   396→                // Apply the new deposit to the state
   397→                let validator_index = state.add_validator_to_registry(
   398→                    deposit_data.pubkey,
   399→                    deposit_data.withdrawal_credentials,
   400→                    deposit_data.amount,
   401→                    spec,
   402→                )?;
   403→                added_validators.push((deposit_data.pubkey, validator_index));
   404→            }
   405→        }
   406→        if conf.effective_balance_updates {
   407→            // Re-process effective balance updates for validators affected by top-up of new validators.
   408→            let (
   409→                validators,
   410→                balances,
   411→                _,
   412→                current_epoch_participation,
   413→                _,
   414→                progressive_balances,
   415→                _,
   416→                _,
   417→            ) = state.mutable_validator_fields()?;
   418→            for (_, validator_index) in added_validators.iter() {
   419→                let balance = *balances
   420→                    .get(*validator_index)
   421→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   422→                let mut validator = validators
   423→                    .get_cow(*validator_index)
   424→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   425→                let validator_current_epoch_participation = *current_epoch_participation
   426→                    .get(*validator_index)
   427→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   428→                process_single_effective_balance_update(
   429→                    *validator_index,
   430→                    balance,
   431→                    &mut validator,
   432→                    validator_current_epoch_participation,
   433→                    &mut next_epoch_cache,
   434→                    progressive_balances,
   435→                    effective_balances_ctxt,
   436→                    state_ctxt,
   437→                    spec,
   438→                )?;
   439→            }
   440→        }
   441→    }
   442→
   443→    // Process consolidations outside the single-pass loop, as they depend on balances for multiple
   444→    // validators and cannot be computed accurately inside the loop.
   445→    if fork_name.electra_enabled() && conf.pending_consolidations {
   446→        process_pending_consolidations(
   447→            state,
   448→            &validators_in_consolidations,
   449→            &mut next_epoch_cache,
   450→            effective_balances_ctxt,
   451→            conf.effective_balance_updates,
   452→            state_ctxt,
   453→            spec,
   454→        )?;
   455→    }
   456→
   457→    // Finally, finish updating effective balance caches. We need this to happen *after* processing
   458→    // of pending consolidations, which recomputes some effective balances.
   459→    if conf.effective_balance_updates {
   460→        let next_epoch_total_active_balance = next_epoch_cache.get_total_active_balance();
   461→        state.set_total_active_balance(next_epoch, next_epoch_total_active_balance, spec);
   462→        let next_epoch_activation_queue =
   463→            activation_queues.map_or_else(ActivationQueue::default, |(_, queue)| queue);
   464→        *state.epoch_cache_mut() =
   465→            next_epoch_cache.into_epoch_cache(next_epoch_activation_queue, spec)?;
   466→    }
   467→
   468→    if conf.proposer_lookahead && fork_name.fulu_enabled() {
   469→        process_proposer_lookahead(state, spec)?;
   470→    }
   471→
   472→    Ok(summary)
   473→}
   474→
   475→// TOOO(EIP-7917): use balances cache
   476→pub fn process_proposer_lookahead<E: EthSpec>(
   477→    state: &mut BeaconState<E>,
   478→    spec: &ChainSpec,
   479→) -> Result<(), Error> {
   480→    let mut lookahead = state.proposer_lookahead()?.clone().to_vec();
   481→
   482→    // Shift out proposers in the first epoch
   483→    lookahead.copy_within((E::slots_per_epoch() as usize).., 0);
   484→
   485→    let next_epoch = state
   486→        .current_epoch()
   487→        .safe_add(spec.min_seed_lookahead.as_u64())?
   488→        .safe_add(1)?;

